public data class Event @JvmOverloads constructor(
    @SerialName("id") public val id: String,
    @SerialName("type") public val type: String,
    @SerialName("timestamp") public val timestamp: Instant,
    /** The client contract the event is written in (§68). */
    @SerialName("contract") public val contract: String,
    @SerialName("task_id") public val taskId: String? = null,
    @SerialName("node_id") public val nodeId: String? = null,
    @SerialName("payload") public val payload: JsonObject? = null,
)

/** A traced request. */
@Serializable
public data class Run @JvmOverloads constructor(
    @SerialName("id") public val id: String,
    /** The client contract the trace is written in (§68). */
    @SerialName("contract") public val contract: String,
    @SerialName("strategy") public val strategy: List<String>,
    @SerialName("status") public val status: String,
    @SerialName("started_at") public val startedAt: Instant,
    @SerialName("models") public val models: List<ModelUse>,
    @SerialName("tools") public val tools: List<ToolUse>,
    @SerialName("nodes") public val nodes: List<String>,
    /** `verification_passes` counts answer checks; Issues and Fixed what they found. */
    @SerialName("verification_passes") public val verificationPasses: Long,
    /** `retries` counts answers tried again on another model. */
    @SerialName("retries") public val retries: Long,
    @SerialName("conversation_id") public val conversationId: String? = null,
    @SerialName("profile_id") public val profileId: String? = null,
    @SerialName("source") public val source: String? = null,
    /** The app that asked: phone, tablet, watch, tv, desktop, or web, or other; empty when it didn't say, such as an API call (#498). */
    @SerialName("client") public val client: String? = null,
    /** Set when the request came from outside the home network. */
    @SerialName("remote") public val remote: Boolean? = null,
    @SerialName("effort") public val effort: String? = null,
    /** The English text; ErrorCode and ErrorDetails let clients show it in the App language (multilingual spec §10). */
    @SerialName("error") public val error: String? = null,
    @SerialName("error_code") public val errorCode: String? = null,
    @SerialName("error_details") public val errorDetails: JsonObject? = null,
    @SerialName("completed_at") public val completedAt: Instant? = null,
    @SerialName("latency_ms") public val latencyMs: Double? = null,
    /** The time before the first model call. */
    @SerialName("pipeline_ms") public val pipelineMs: Double? = null,
    /** How many parts a plan had; 0 when there was no plan. */
    @SerialName("workers") public val workers: Long? = null,
    @SerialName("parallel") public val parallel: Boolean? = null,
    @SerialName("verification_issues") public val verificationIssues: Long? = null,
    @SerialName("verification_fixed") public val verificationFixed: Long? = null,
    @SerialName("context_tokens") public val contextTokens: Long? = null,
    @SerialName("context_limit") public val contextLimit: Long? = null,
    /** `cache_hits` counts tool calls answered from a cache, by tool (§36). */
    @SerialName("cache_hits") public val cacheHits: Map<String, Long>? = null,
    /** What an Enforce profile's topic check found (#345): on_topic, small_talk, off_topic when the set reply went out without an answer, or answer_off_topic when the answer was replaced by it. */
    @SerialName("topic") public val topic: String? = null,
)

/** One model's part in a run. */
@Serializable
public data class ModelUse @JvmOverloads constructor(
    @SerialName("model_id") public val modelId: String,
    @SerialName("calls") public val calls: Long,
    @SerialName("prompt_tokens") public val promptTokens: Long,
    @SerialName("completion_tokens") public val completionTokens: Long,
    @SerialName("cached_tokens") public val cachedTokens: Long,
    @SerialName("role") public val role: String? = null,
    @SerialName("node") public val node: String? = null,
    /** Time spent starting the model for this run, if it had to. */
    @SerialName("load_ms") public val loadMs: Double? = null,
    /** The wait for the first token of the first call, including loading. */
    @SerialName("first_token_ms") public val firstTokenMs: Double? = null,
    @SerialName("ttft_ms") public val ttftMs: Double? = null,
    @SerialName("tok_per_sec") public val tokPerSec: Double? = null,
    /** `backend` and Device ran the model, such as vulkan and "AMD Radeon RX 7900 XTX" (#317); empty when not known, such as on a paired computer. */
    @SerialName("backend") public val backend: String? = null,
    @SerialName("device") public val device: String? = null,
)

