    @SerialName("client") public val client: String,
    @SerialName("cold") public val cold: Boolean,
    @SerialName("runs") public val runs: Long,
    /** The median wait from the request to the first token; FirstWordP90Ms is the wait nine in ten answers beat. */
    @SerialName("first_word_ms") public val firstWordMs: Double,
    @SerialName("first_word_p90_ms") public val firstWordP90Ms: Double,
    /** `remote` counts the runs that came from outside the home network. */
    @SerialName("remote") public val remote: Long? = null,
    /** The median time spent loading models; 0 when warm. */
    @SerialName("load_ms") public val loadMs: Double? = null,
