/** What an assistant answer used and did. */
@Serializable
public data class MessageMeta @JvmOverloads constructor(
    @SerialName("sources") public val sources: List<Citation>? = null,
    @SerialName("steps") public val steps: List<ActivityStep>? = null,
    /** `notice` tells the user something changed that may affect the answer, such as a smaller model answering after the chosen one failed. */
    @SerialName("notice") public val notice: String? = null,
    /** Attached to a question or produced with an answer. */
    @SerialName("files") public val files: List<FileRef>? = null,
    /** `run_id` names the run trace behind the answer (§35), at GET /api/v1/runs/{id}. */
    @SerialName("run_id") public val runId: String? = null,
    /** The client contract the metadata was written in (§68). Metadata saved before the contract existed has none, and reads as 1.0. */
    @SerialName("contract") public val contract: String? = null,
    @SerialName("setup") public val setup: SetupOffer? = null,
    @SerialName("context") public val context: ContextUsage? = null,
    /** `backend` and Device ran the answer, such as vulkan and "AMD Radeon RX 7900 XTX", or cpu and "" (#317, contract 1.8), so a client such as the iPhone app can say whether it came from the GPU. Empty when not known, such as when a step ran on a paired computer. */
    @SerialName("backend") public val backend: String? = null,
    @SerialName("device") public val device: String? = null,
    @SerialName("automation") public val automation: AutomationDraft? = null,
    @SerialName("automation_run") public val automationRun: AutomationRun? = null,
    /** How the answer was reached when its profile deliberates: the drafts compared and the outcome (#459, contract 1.23). */
    @SerialName("deliberation") public val deliberation: MessageMetaDeliberation? = null,
    /** How long a reasoning model thought before it answered, and what it thought (#701, contract 1.43). */
    @SerialName("reasoning") public val reasoning: MessageMetaReasoning? = null,
)

