    /** The knowledge source name or the file path. */
    @SerialName("source") public val source: String? = null,
    @SerialName("snippet") public val snippet: String? = null,
    /** The chat file a file citation names, so a client can offer it for download (contract 1.9). */
    @SerialName("artifact_id") public val artifactId: String? = null,
)

