/** Offers to install a missing ability, such as image generation, and to finish the request once it is ready. */
@Serializable
public data class SetupOffer @JvmOverloads constructor(
    /** The inventory ability, such as image_generation. */
    @SerialName("ability") public val ability: String,
    @SerialName("label") public val label: String,
    /** What to install: for image_generation, the model id for POST /api/v1/images/setup. */
    @SerialName("option") public val option: String,
    @SerialName("name") public val name: String,
    @SerialName("size_bytes") public val sizeBytes: Long,
    @SerialName("node_id") public val nodeId: String? = null,
    @SerialName("node_name") public val nodeName: String? = null,
    /** The message to send again once it is set up; empty for a question about the ability. */
    @SerialName("request") public val request: String? = null,
    /** `slow` says the computer it runs on has no GPU acceleration for it, so each picture takes minutes and a clip can take most of an hour (contract 1.12). */
    @SerialName("slow") public val slow: Boolean? = null,
    /** `tight_memory` says the computer has less memory than the model is comfortable with, so it may be slow or fail (contract 1.12). */
    @SerialName("tight_memory") public val tightMemory: Boolean? = null,
    /** Works, tight (set up only when the person agrees), or unsupported; for tight, Short is what it's short of (memory, graphics for a card's own memory, or shared for the share of memory Apple silicon's graphics may use), NeedBytes what the model needs of it, and HaveBytes what the computer has (contract 1.34, #550). */
    @SerialName("verdict") public val verdict: String? = null,
    @SerialName("short") public val short: String? = null,
    @SerialName("need_bytes") public val needBytes: Long? = null,
    @SerialName("have_bytes") public val haveBytes: Long? = null,
    /** `remote` says NodeID is a paired computer, not this one, and FreeBytes is its free disk space when known (contract 1.14, #153). The app sets it up there with ?node_id= on the setup routes. */
    @SerialName("remote") public val remote: Boolean? = null,
    @SerialName("free_bytes") public val freeBytes: Long? = null,
    /** The files to send again with Request, such as the pictures a vision model is set up to look at (contract 1.28, #529). For ability "vision", Option is the model id for POST /api/v1/models/{id}/install. */
    @SerialName("attachments") public val attachments: List<String>? = null,
    /** `reason` and Fit are for a model offer (#707, contract 1.45; ability model): why the model would answer this kind of request better (coding, data, language, reasoning, or context), and how well it fits this computer (excellent or good). Request is then answered again with Option. */
    @SerialName("reason") public val reason: String? = null,
    @SerialName("fit") public val fit: String? = null,
)

